// ── GitHub raw fetch helpers ──
const RAW = `https://raw.githubusercontent.com/${GH.owner}/${GH.repo}/${GH.branch}/`;
const API = `https://api.github.com/repos/${GH.owner}/${GH.repo}/contents/`;

async function ghJSON(path) {
  const r = await fetch(RAW + path, {signal: AbortSignal.timeout(8000)});
  if (!r.ok) throw new Error(`${r.status} – ${path}`);
  return r.json();
}
async function ghMD(path) {
  const r = await fetch(RAW + path, {signal: AbortSignal.timeout(8000)});
  if (!r.ok) throw new Error(`${r.status} – ${path}`);
  return r.text();
}

// ── Generic skeleton helper ──
function skeletons(n=5){
  return Array.from({length:n},(_,i)=>`<div class="skeleton" style="height:13px;width:${65+i*7}%;margin-bottom:8px;"></div>`).join('');
}
function showError(el, msg){
  el.innerHTML = `<div class="page-error">⚠ GitHub fetch failed: <strong>${msg}</strong><br><small>Check repo/file path in the GH config block at the top of the script.</small></div>`;
}

// ══════════════════════════════════════════════════════════
//  NAVIGATION
// ══════════════════════════════════════════════════════════
const PAGE_TITLES = {overview:'Overview',environments:'Environments',models:'Models Registry',tools:'Tools',docs:'Documentation',calculators:'Calculators'};
let _loaded = {};
let docsInited = false;

function navTo(page, btn){
  document.querySelectorAll('.page').forEach(p=>p.classList.remove('active'));
  document.querySelectorAll('.nav-btn').forEach(b=>b.classList.remove('active'));
  document.getElementById('page-'+page).classList.add('active');
  btn.classList.add('active');
  document.getElementById('page-title').textContent = PAGE_TITLES[page];
  if(!_loaded[page]) { _loaded[page]=true; loadPage(page); }
}

function loadPage(page){
  if(page==='overview')     loadOverview();
  if(page==='environments') loadEnvironments();
  if(page==='models')       loadModels();
  if(page==='tools')        loadTools();
  if(page==='docs')         initDocsPage();
  if(page==='calculators')  recalc();
}

// Auto-load overview on start
window.addEventListener('DOMContentLoaded', ()=>{ _loaded['overview']=true; loadPage('overview'); });

